    "questionAr": "قضيب منتظم $AB$ طوله $120\\text{ سم}$ ووزنه $20\\text{ ن}$ يرتكز على حاملين عند طرفيه $A$ و $B$. وُضع ثقل $P = 80\\text{ ن}$ على بعد $30\\text{ سم}$ من $A$. أوجد رد الفعلين $R_A$ و $R_B$.",
