      "2. Load $P = 80\\text{ N}$ is at $30\\text{ cm}$ from $A$, which is $90\\text{ cm}$ from $B$.",
      "3. Take moments about $B$ ($sum M_B = 0$):",
      "   $R_A(120) = 20(60) + 80(90) = 1200 + 7200 = 8400$.",
      "   $R_A = \\frac{8400}{120} = 70\\text{ N}$.",
      "4. Vertical equilibrium: $R_B = 20 + 80 - 70 = 30\\text{ N}$."
