    "questionEn": "Two parallel forces $F_1 = 40\\text{ N}$ at $A$ and $F_2 = 10\\text{ N}$ at $B$ act in opposite directions, where $AB = 150\\text{ cm}$. Find the distance $AC$ from point $A$ to the line of action of their resultant.",
    "questionAr": "تؤثر قوتان متوازيتان متضادتان في الاتجاه $F_1 = 40\\text{ ن}$ عند $A$ و $F_2 = 10\\text{ ن}$ عند $B$، حيث $AB = 150\\text{ سم}$. أوجد بعد نقطة تأثير المحصلة $C$ عن النقطة $A$.",
    "optionsEn": [
      "$AC = 50\\text{ cm}$ beyond $A$",
      "$AC = 55\\text{ cm}$ beyond $A$",
      "$AC = 60\\text{ cm}$ beyond $A$",
      "$AC = 65\\text{ cm}$ beyond $A$"
    ],
    "optionsAr": [
      "$AC = 50\\text{ سم}$ خارج القطعة من جهة $A$",
      "$AC = 55\\text{ سم}$ خارج القطعة من جهة $A$",
      "$AC = 60\\text{ سم}$ خارج القطعة من جهة $A$",
      "$AC = 65\\text{ سم}$ خارج القطعة من جهة $A$"
    ],
    "correctAnswer": "$AC = 50\\text{ cm}$ beyond $A$",
    "correctIndex": 0,
    "hintEn": "40 * AC = 10 * (AB + AC).",
    "hintAr": "$40 \\times AC = 10 \\times (AB + AC)$.",
    "stepByStepSolutionEn": [
      "1. The resultant acts outside $AB$ on the side of the larger force $F_1$ at $A$.",
      "2. Taking moments about $C$: $40 \\times AC = 10 \\times BC = 10 \\times (150 + AC)$.",
      "3. $40 AC = 1500 + 10 AC \\implies 30 AC = 1500 \\implies AC = 50\\text{ cm}$."
    ],
    "stepByStepSolutionAr": [
      "١. المحصلة تؤثر خارج القطعة $AB$ من جهة القوة الكبرى ($A$).",
      "٢. العزوم حول $C$: $40 \\times AC = 10 \\times (150 + AC)$.",
      "٣. $30 AC = 1500 \\implies AC = 50\\text{ سم}$."
    ],
    "teacherTipEn": "For ratio 4:1, the external segment AC is 1/3 of AB.",
    "teacherTipAr": "عندما تكون نسبة القوتين ٤ : ١، فإن الجزء الخارجي أ جـ يساوي ثلث طول القطعة أ ب."
