      "   Take moments about $C$: $w_1 \\times AC = W \\times (x_G - AC) \\implies 180 \\times 20 = W(x_G - 20) \\implies W(x_G - 20) = 3600$.",
      "2. Second tipping case (about $D$, $R_C = 0$):",
      "   Position of $D$ is $100 - 30 = 70\\text{ cm}$.",
      "   Take moments about $D$: $W \\times (70 - x_G) = w_2 \\times DB \\implies W(70 - x_G) = 120 \\times 30 = 3600$.",
      "3. Since $3600 = 3600 = 3600$:",
      "   $x_G - 20 = 70 - x_G \\implies 2x_G = 90 \\implies x_G = 45\\text{ cm}$.",
      "4. Substitute $x_G = 45$: $W(45 - 20) = 3600 \\implies 25 W = 3600 \\implies W = 144\\text{ N}$."
